"""Tests for ``docs_macros.render``, ``docs_macros.sync``, and autogenerated ``docs/`` synchronization."""

import sys
from collections.abc import Callable
from pathlib import Path
from typing import Final

import pytest
from zensical.extensions.macros import MacroEnv, _load_module

from docs_macros import define_env
from docs_macros.__main__ import main as docs_macros_cli_main
from docs_macros.constants import DOCS_DIR, REPO_ROOT, SCHEMAS_SUBDIR, TEMPLATES_DIR
from docs_macros.render import (
    create_jinja_env,
    render_converter_spec,
    render_macro_stub,
    render_pipeline_spec,
    render_reference_table,
)
from docs_macros.sync import (
    GENERATED_MACRO_STUB_RE,
    DocsGenerationPaths,
    build_generated_docs_plan,
    clean_generated_docs,
    discover_spec_names,
    sync_generated_docs,
)
from tests.docs.helpers import (
    FRONT_MATTER_RE,
    excluded_doc_names,
    materialize_markdown_file,
    materialize_markdown_text,
    resolve_markdown_sources,
    should_ignore_docs_collect,
)

pytestmark = pytest.mark.docs

EXPECTED_TEMPLATE_COUNT: Final[int] = 15
EXPECTED_MACRO_STUB_COUNT: Final[int] = 13
TEMPLATE_FILES: Final[tuple[str, ...]] = tuple(
    sorted(p.relative_to(TEMPLATES_DIR).as_posix() for p in TEMPLATES_DIR.rglob("*.md.j2"))
)
PLANNED_DOCS: Final[dict[Path, str]] = build_generated_docs_plan()
PLANNED_MD_STUBS: Final[tuple[tuple[Path, str], ...]] = tuple(
    (rel_path, text) for rel_path, text in PLANNED_DOCS.items() if rel_path.suffix == ".md"
)


@pytest.fixture(scope="module")
def staged_generated_docs(tmp_path_factory: pytest.TempPathFactory) -> Path:
    """Materialize the planned autogenerated docs once for macro stub rendering assertions.

    :param tmp_path_factory: Pytest session temporary directory factory.
    :type tmp_path_factory: pytest.TempPathFactory
    :return: Directory containing materialized autogenerated documentation files.
    :rtype: Path
    """
    staged_docs = tmp_path_factory.mktemp("staged_docs")
    sync_generated_docs(DocsGenerationPaths(docs_dir=staged_docs))
    return staged_docs


@pytest.mark.parametrize(
    "rel_template",
    TEMPLATE_FILES,
    ids=[rel.removesuffix(".md.j2").replace("/", "-") for rel in TEMPLATE_FILES],
)
def test_jinja_template_compiles_pass(rel_template: str) -> None:
    """Verify each .md.j2 template compiles without error under StrictUndefined."""
    env = create_jinja_env()
    compiled = env.get_template(rel_template)
    assert compiled.name == rel_template


def test_jinja_templates_inventory_and_strict_macro_registration_pass(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    """Verify all 15 .md.j2 templates exist and register macros without mutating docs/."""
    assert len(TEMPLATE_FILES) == EXPECTED_TEMPLATE_COUNT

    before_docs_entries = sorted(p.relative_to(DOCS_DIR).as_posix() for p in DOCS_DIR.rglob("*"))
    for mod_key in [k for k in sys.modules if k == "docs_macros" or k.startswith("docs_macros.")]:
        monkeypatch.delitem(sys.modules, mod_key)

    macro_env = MacroEnv(conf={"root_dir": str(REPO_ROOT), "docs_dir": "docs"})
    _load_module(macro_env, "docs_macros", REPO_ROOT)
    assert set(macro_env.macros) == {
        "render_cli_reference",
        "render_bundled_schemas",
        "render_converter_spec",
        "render_pipeline_spec",
        "render_reference_table",
    }
    assert set(macro_env.filters) == {"escape_cell", "code_fence"}
    define_env(macro_env)
    after_docs_entries = sorted(p.relative_to(DOCS_DIR).as_posix() for p in DOCS_DIR.rglob("*"))
    assert after_docs_entries == before_docs_entries


def test_generated_docs_plan_and_sync_inventory_pass(tmp_path: Path) -> None:
    """Verify planned Markdown stub count and sync_generated_docs expected path count match."""
    assert len(PLANNED_MD_STUBS) == EXPECTED_MACRO_STUB_COUNT
    sync_res = sync_generated_docs(DocsGenerationPaths(docs_dir=tmp_path / "docs"))
    assert len(sync_res.expected_paths) == len(PLANNED_DOCS)


@pytest.mark.parametrize(
    ("rel_path", "stub_text"),
    [pytest.param(rel_path, stub_text, id=rel_path.stem) for rel_path, stub_text in PLANNED_MD_STUBS],
)
def test_macro_stub_page_renders_via_zensical_loader_pass(
    staged_generated_docs: Path,
    rel_path: Path,
    stub_text: str,
) -> None:
    """Verify each planned render_macros: true stub page renders non-empty Markdown with an H1 heading."""
    assert FRONT_MATTER_RE.match(stub_text) is not None
    rendered = materialize_markdown_text(stub_text)
    assert rendered.strip().startswith("# "), f"{rel_path.name} did not render an H1 title"
    assert "{{" not in rendered or "```" in rendered
    assert materialize_markdown_file(staged_generated_docs / rel_path) == rendered


