def test_resolve_markdown_sources_reads_disk_files(tmp_path: Path) -> None:
    """Verify resolve_markdown_sources reads relative paths and UTF-8 content for existing Markdown files."""
    nested_md = tmp_path / "docs" / "guide.md"
    nested_md.parent.mkdir(parents=True)
    nested_md.write_text("# Guide\n", encoding="utf-8")
    assert resolve_markdown_sources([nested_md], repo_root=tmp_path) == [("docs/guide.md", "# Guide\n")]
